// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Receiver owner;

    function setUp() public {
        // Owner must be able to receive the payout via transfer, so deploy C
        // from a minimal payable receiver (Owner = msg.sender in C).
        owner = new Receiver();
        vm.prank(address(owner));
        c = new MultiplicatorX4();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint96).max);

        // fund the contract directly with an admissible amount
        vm.deal(address(c), amount);

        // Owner withdraws: in the reference this transfers the whole balance out
        vm.prank(address(owner));
        c.withdraw();

        // Rule: after a successful Owner withdraw, the contract holds no Ether.
        assertTrue(address(c).balance == 0);
    }
}

contract Receiver {
    receive() external payable {}
}
